<?php require_once 'config/config.php';require_login();$title='Dashboard';$id=(int)user()['id'];$s=db()->prepare("SELECT r.* FROM favourites f JOIN recipes r ON r.id=f.recipe_id WHERE f.user_id=? ORDER BY f.created_at DESC");$s->execute([$id]);$favs=$s->fetchAll();$s=db()->prepare("SELECT * FROM recipes WHERE author_id=? ORDER BY created_at DESC");$s->execute([$id]);$subs=$s->fetchAll();require 'includes/header.php';?><div class="page-hero"><div class="container"><span class="eyebrow">Your kitchen</span><h1 class="fw-bold">Welcome, <?=e(user()['first_name'])?>.</h1></div></div><section class="section"><div class="container"><div class="row g-3 mb-5"><div class="col-md-4"><div class="stat">Saved recipes<h2><?=count($favs)?></h2></div></div><div class="col-md-4"><div class="stat">Submissions<h2><?=count($subs)?></h2></div></div><div class="col-md-4"><div class="stat">Account<h2>Active</h2></div></div></div><h3>Favourite recipes</h3><div class="row g-4 mb-5"><?php foreach($favs as $r):?><div class="col-md-4"><div class="card recipe-card"><img src="<?=recipe_image($r['image'])?>" alt=""><div class="card-body"><h5><?=e($r['title'])?></h5><a href="pages/recipe.php?id=<?=$r['id']?>" class="btn btn-sm btn-outline-dark">View</a></div></div></div><?php endforeach;if(!$favs):?><p class="text-muted">No favourites yet.</p><?php endif;?></div><h3>Your submissions</h3><div class="table-responsive"><table class="table"><tr><th>Recipe</th><th>Status</th></tr><?php foreach($subs as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div></div></section><?php require 'includes/footer.php';?>